import { join } from 'path'

/**
 * The **single** rule for "runtime environment → app name / userData directory".
 *
 * Why this isolation layer is needed (real-machine user report on 2026-11-24):
 * the package.json in packaged builds is generated by electron-builder and has **no** productName; the dev
 * package.json has none either. So `app.getName()` is `ryten-bench` on both sides, and
 * `app.getPath('userData')` also points to the same `%APPDATA%\ryten-bench` —
 * settings (settings.json), the PGlite database (RytenBenchDB), plugin packages (plugins/), account spaces
 * (profiles/), the keystore, session files, and logs are all shared. The result: "starting a test with `pnpm dev`"
 * reads and writes the packaged build's data — develop for a while and real data gets modified; conversely, install a
 * package and you see the dev database.
 *
 * Directory convention (confirmed by the user):
 * - production (packaged build, `app.isPackaged === true`): `<appData>/ryten-bench`
 *   — identical to historic releases, so existing users upgrade without changing directories or losing data;
 * - development (`pnpm dev` / `pnpm start` / running `electron .` directly): `<appData>/ryten-bench-dev`
 *   — development, debugging, and test tooling can do whatever they like without touching release data.
 *
 * `<appData>` is obtained by the caller from `app.getPath('appData')` (Windows `%APPDATA%`,
 * macOS `~/Library/Application Support`, Linux `$XDG_CONFIG_HOME` or `~/.config`).
 * `process.platform` is deliberately not read here: path joining is left to path.join, so the pure function can be covered directly by unit tests.
 */
export type AppEnvironmentName = 'development' | 'production'

/** Application name for packaged builds (shown in the system menu / About panel / macOS log directory) */
export const PRODUCTION_APP_NAME = 'RytenBench'
/** Application name in development: distinct from the release build so the two sets of windows/logs do not share a name in the system */
export const DEVELOPMENT_APP_NAME = 'RytenBench Dev'
/** userData directory name for packaged builds: historic path, cannot change (release users' data lives here) */
export const PRODUCTION_DATA_DIR = 'ryten-bench'
/** userData directory name in development: an independent data set */
export const DEVELOPMENT_DATA_DIR = 'ryten-bench-dev'

export interface EnvironmentInputs {
  /** `app.isPackaged`: true for packaged builds, false for `electron .` / electron-vite dev */
  packaged: boolean
  /** `app.getPath('appData')`: the cross-platform per-user application data root */
  appDataDir: string
}

export interface AppEnvironment {
  name: AppEnvironmentName
  /** Display name written into `app.setName()` */
  appName: string
  /** userData directory name (`<appDataDir>/<dataDirName>`) */
  dataDirName: string
  /** Regular userData directory; when overridden by `--user-data-dir`, the process does not actually use it */
  userDataDir: string
}

export function resolveEnvironment(inputs: EnvironmentInputs): AppEnvironment {
  const dataDirName = inputs.packaged ? PRODUCTION_DATA_DIR : DEVELOPMENT_DATA_DIR
  return {
    name: inputs.packaged ? 'production' : 'development',
    appName: inputs.packaged ? PRODUCTION_APP_NAME : DEVELOPMENT_APP_NAME,
    dataDirName,
    userDataDir: join(inputs.appDataDir, dataDirName)
  }
}

/** Depends only on `hasSwitch`, so the pure function can also accept Electron's `app.commandLine` or a test double */
export interface CommandLineLike {
  hasSwitch?(name: string): boolean
}

/**
 * Automation (`test/probe-*.mjs`, CI smoke) uses `--user-data-dir=...` to carve out a temporary directory for itself.
 *
 * Such processes must not be overridden again by the environment defaults: otherwise one test run would write into the
 * real data directory (`storage/layout.ts` also relies on this check to decide "do not move the data/ next to the install
 * directory around"). The command-line switch may be written as `--user-data-dir=...` or split into two argv entries
 * (`--user-data-dir` + path), and Electron itself also parses it into `app.commandLine`, so all three forms must be recognized.
 */
export function hasUserDataDirOverride(
  argv: readonly string[],
  commandLine?: CommandLineLike
): boolean {
  if (commandLine?.hasSwitch?.('user-data-dir') === true) return true
  return argv.some((arg) => arg === '--user-data-dir' || arg.startsWith('--user-data-dir='))
}
